207	    /**
208	     * Returns the value of the current request's {@code Idempotency-Key} header, or {@code null} when
209	     * the request carries no such header (or there is no active servlet request). Reading it from the
210	     * request context here keeps the header — a request-level concern surrounding the create — out of
211	     * the generated {@link #addOwner} signature and the {@link #createOwner} pipeline.
212	     *
213	     * @return the {@code Idempotency-Key} header value, or {@code null} when absent
214	     */
215	    private String currentIdempotencyKey() {
216	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
217	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
218	            return servletAttributes.getRequest().getHeader("Idempotency-Key");
219	        }
220	        return null;
221	    }
222	
223	    /**
224	     * Runs the full owner-creation pipeline for a create request and returns the 201 Created
225	     * response for the newly persisted owner: the request fields are mapped and normalized, every
226	     * create-time policy (per-day and per-city quota, household membership, identity duplicate and
227	     * soft-duplicate) is applied in order, the create-time derived fields are assigned, the owner is
228	     * saved and audited, and a {@code Location} header for the new owner is set. Keeping the pipeline
229	     * in its own method leaves {@link #addOwner} as the thin request entry point, so request-level
230	     * concerns that merely surround a create (rather than being one of its steps) can be layered in
231	     * {@code addOwner} without disturbing the creation steps gathered here.
232	     *
233	     * @param ownerFieldsDto the submitted owner fields
234	     * @return a 201 Created response carrying the persisted owner and its {@code Location} header
235	     */
236	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
237	        HttpHeaders headers = new HttpHeaders();
238	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
239	        normalizeOwnerFields(owner);
240	        // Enforce the pre-persistence policies that can reject the new owner outright.
241	        rejectDisallowedOwnerCreation(owner);
242	        // Resolve the owner's household membership: assign the deterministic 'householdId' (a pure
243	        // function of last name and postcode), cap the membership level for a new household member,
244	        // and record the household size. The household id is no longer part of the identity key, so
245	        // this no longer rejects a household duplicate: owners sharing a household are distinguished
246	        // by the identity-key check below and otherwise flagged as soft duplicates.
247	        boolean declaredHouseholdMember =
248	            applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
249	        // Reject the create when the owner's whole derived identity key (the SHA-256 over normalized
250	        // telephone, lower-cased email and the Soundex of the last name) already matches an existing
251	        // owner. This single rule subsumes the former separate telephone, email and household
252	        // duplicate checks.
253	        rejectWhenIdentityInUse(owner);
254	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
255	        // shares an existing owner's last name and postcode with a different telephone. A declared
256	        // household member is never flagged: it is a known member, not a suspected duplicate.
257	        assignPossibleDuplicate(owner, declaredHouseholdMember);
258	        // Assign the remaining create-time derived fields (namesake count, member id
259	        // and bulk-signup warning), each fixed at creation time.
260	        assignDerivedFields(owner);
261	        // Assign the (household-capped) membership level, fixed at creation time. This runs after the
262	        // derived fields above because the level is computed from the membership points, which depend
263	        // on the namesake count assigned in assignDerivedFields.
264	        assignMembershipLevel(owner);
265	        this.clinicService.saveOwner(owner);
266	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
267	        // Record the successful create on the dedicated AUDIT log.
268	        auditOwnerCreated(owner, ownerDto);
269	        // Enqueue the welcome notification for the newly created owner.
270	        enqueueWelcomeNotification(owner);
271	        headers.setLocation(UriComponentsBuilder.newInstance()
