363	    /**
364	     * Applies the household-membership rules for a newly normalized owner being created. The
365	     * household id is a deterministic function of the owner's last name and postcode, so owners
366	     * with the same last name and postcode share it automatically; it is assigned to the new owner
367	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
368	     * same last name and postcode is a member of the same household. A new owner may join an
369	     * existing household: rather than the create being rejected, the newcomer's membership level is
370	     * capped at one above the household's current maximum (see {@link #assignMembershipLevel}). When
371	     * the request declares it shares the household via {@code sharesHousehold} the owner is a known,
372	     * declared member and is never flagged as a possible duplicate. The owner's
373	     * {@code householdSize} (the number of owners sharing the household after this create) is
374	     * recorded either way.
375	     *
376	     * @param owner           the newly mapped and normalized owner being created
377	     * @param sharesHousehold whether the request declared that the owner shares an existing household
378	     * @return {@code true} if the owner joined an existing household as a declared member
379	     */
380	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
381	        // Assign the deterministic household id (a pure function of last name and postcode) so every
382	        // owner with the same last name and postcode shares it automatically.
383	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
384	        // Identify any existing owners in the same household (same computed household id). A new owner
385	        // may join an existing household: its membership level is capped at one above the household's
386	        // current maximum (see assignMembershipLevel) rather than the create being rejected outright.
387	        List<Owner> householdMembers = sameHouseholdOwners(owner);
388	        // An owner that joins an existing household while the request declares it shares that
389	        // household is a known, declared member and so is never flagged as a possible duplicate.
390	        boolean declaredHouseholdMember = !householdMembers.isEmpty() && sharesHousehold;
391	        // Record the size of this owner's household after this create, fixed at creation time.
392	        owner.setHouseholdSize(householdMembers.size() + 1);
393	        return declaredHouseholdMember;
394	    }
