396	    /**
397	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
398	     * has already been resolved: the namesake count, the per-city member id, the bulk-signup warning
399	     * flag and the city capacity warning flag. Each value is fixed at creation time and is
400	     * independent of the others. Grouping them
401	     * here keeps {@link #addOwner} focused on the high-level create sequence.
402	     *
403	     * @param owner the owner being created, already normalized and with its household resolved
404	     */
405	    private void assignDerivedFields(Owner owner) {
406	        // Record how many existing owners already share this owner's first and last name
407	        // (compared case-insensitively) before this create, fixed at creation time.
408	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
409	        // Assign the member id '<REGION><FY><HASH8><CHK>' from the region derived from the postcode,
410	        // the 2-digit fiscal year of the registration date, an 8-hex-character hash of the normalized
411	        // telephone and last name, and a Luhn check digit over the preceding digits, fixed at
412	        // creation time.
413	        owner.setMemberId(memberId(owner));
414	        // Flag the create when more than 80 owners have already been created on this owner's
415	        // (adjusted business-day) registration date, fixed at creation time.
416	        owner.setBulkSignupWarning(
417	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
418	        // Flag the create when the owner's city is approaching its capacity limit: it already holds
419	        // between CAPACITY_WARNING_THRESHOLD and MAX_OWNERS_PER_CITY - 1 owners (40-49). A city at or
420	        // over the limit is rejected earlier (see rejectWhenCityAtCapacity), so this is never reached
421	        // for a full city. Fixed at creation time.
422	        int cityOwners = countOwnersInCity(owner.getCity());
423	        owner.setCapacityWarning(
424	            cityOwners >= CAPACITY_WARNING_THRESHOLD && cityOwners < MAX_OWNERS_PER_CITY);
425	    }
