427	    /**
428	     * Assigns the new owner's membership level, capped by their household, and fixes it at creation
429	     * time. The level a newly created owner would earn from their membership points cannot exceed
430	     * one above the current maximum membership level among their existing household members (the
431	     * owners already sharing this owner's household id); the capped value is stored so it is returned
432	     * unchanged on later reads. When the owner has no existing household member no cap applies and
433	     * the plain points-derived level is used.
434	     *
435	     * @param owner the owner being created, already normalized and with its derived fields assigned
436	     */
437	    private void assignMembershipLevel(Owner owner) {
438	        int level = ownerMapper.membershipLevel(ownerMapper.membershipPoints(owner));
439	        List<Owner> householdMembers = sameHouseholdOwners(owner);
440	        if (!householdMembers.isEmpty()) {
441	            int maxMemberLevel = householdMembers.stream()
442	                .mapToInt(this::memberLevel)
443	                .max()
444	                .getAsInt();
445	            level = Math.min(level, maxMemberLevel + 1);
446	        }
447	        owner.setMembershipLevel(level);
448	    }
