450	    /**
451	     * Returns an existing household member's membership level for the purpose of capping a new
452	     * member's level: the level stored on the member when present (the already-capped value fixed at
453	     * its own creation), otherwise the level derived from its membership points (for members created
454	     * before the level was persisted).
455	     *
456	     * @param member an existing owner in the same household
457	     * @return the member's membership level
458	     */
459	    private int memberLevel(Owner member) {
460	        return member.getMembershipLevel() != null
461	            ? member.getMembershipLevel()
462	            : ownerMapper.membershipLevel(ownerMapper.membershipPoints(member));
463	    }
