465	    /**
466	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
467	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) is the SHA-256 hex over
468	     * the normalized telephone, the lower-cased email (or empty) and the Soundex of the last name, so
469	     * this single rule replaces the former separate telephone, email and household duplicate checks:
470	     * two owners collide only when their whole keys are equal, and members of one household with
471	     * different telephones have different keys and are both allowed (instead flagged as soft
472	     * duplicates).
473	     *
474	     * @param owner the owner being created, already normalized
475	     */
476	    private void rejectWhenIdentityInUse(Owner owner) {
477	        String identityKey = owner.getIdentityKey();
478	        boolean inUse = existingOwners()
479	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
480	        if (inUse) {
481	            throw new DuplicateIdentityException(
482	                "An owner with identity key " + identityKey + " already exists");
483	        }
484	    }
