486	    /**
487	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
488	     * duplicate (identity-key) check. When an existing owner has a different identity key but shares
489	     * this owner's postcode and the Soundex code of its last name, the new owner is still created but
490	     * flagged as a possible duplicate: {@code possibleDuplicate} is set true and
491	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
492	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
493	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
494	     * possible duplicate. A declared household member is never flagged: it is a known member of the
495	     * household, not a suspected duplicate. Both values are fixed at creation time.
496	     *
497	     * @param owner                   the owner being created, already normalized and confirmed not a
498	     *                                hard duplicate
499	     * @param declaredHouseholdMember whether the owner joined an existing household as a declared
500	     *                                member
501	     */
502	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
503	        Integer matchId = declaredHouseholdMember || owner.getPostcode() == null ? null : existingOwners()
504	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
505	            .map(Owner::getId)
506	            .min(Integer::compareTo)
507	            .orElse(null);
508	        owner.setPossibleDuplicate(matchId != null);
509	        owner.setPossibleDuplicateOf(matchId);
510	    }
