512	    /**
513	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
514	     * two have different identity keys (an equal key would already have been rejected as a hard
515	     * duplicate) but share a postcode (required on both sides, so an owner without a postcode never
516	     * matches) and the Soundex code of their last name. A match flags the new owner as a possible
517	     * duplicate of the existing one without rejecting the create.
518	     *
519	     * @param existing an existing owner to compare against
520	     * @param owner    the owner being created
521	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
522	     */
523	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
524	        return existing.getPostcode() != null
525	            && existing.getPostcode().equals(owner.getPostcode())
526	            && Soundex.encode(existing.getLastName()).equals(Soundex.encode(owner.getLastName()))
527	            && !existing.getIdentityKey().equals(owner.getIdentityKey());
528	    }
