556	    /**
557	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
558	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
559	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
560	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
561	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
562	     * server's current date. Canonicalising the address here, before the household checks read it,
563	     * ensures duplicate detection and the shared household id both compare the normalized form.
564	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
565	     * duplicate, household and member-id rules.
566	     *
567	     * @param owner the newly mapped owner to canonicalize
568	     */
569	    private void normalizeOwnerFields(Owner owner) {
570	        // Canonicalize the owner's address fields on create so the address is stored and returned in
571	        // canonical form and every later comparison (household duplicate detection and the shared
572	        // household id) uses it. A value that is blank after normalization is rejected with 400.
573	        normalizeAddressFields(owner);
574	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
575	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
576	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
577	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
578	        // Store the (already syntactically validated) email lower-cased so it is persisted and
579	        // returned in canonical form. A missing email is left untouched.
580	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
581	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
582	        // canonicalization so the comparison sees the lower-cased value.
583	        rejectDisposableEmailDomain(owner.getEmail());
584	        // Validate the optional postcode against the fixed range for the city's region. A postcode
585	        // is checked only when present (it is optional); one out of range for the city's region is
586	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
587	        // value is left unchanged.
588	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
589	        // Reject a supplied registration date that is later than the server's current date with
590	        // 400, before any defaulting or business-day adjustment, so a future date is never
591	        // persisted regardless of how the roll-forward would move it.
592	        rejectFutureRegistrationDate(owner.getRegistrationDate());
593	        // Default the registration date to the server's current date when the client did not
594	        // supply one, then roll the effective date forward to a business day so a Saturday or
595	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
596	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
597	        // date-derived field (such as the member id's fiscal-year segment) and the per-day
598	        // create-limit are computed from.
599	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
600	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
601	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
602	    }
603	
604	    /**
605	     * Canonicalizes a newly mapped owner's address on create, in place, so it is persisted and
606	     * returned in canonical form. The owner may supply its address in either of two forms and the
607	     * structured form is preferred when present: when a non-blank {@code addressLine1} is supplied it
608	     * (and the optional {@code addressLine2}) is normalized (trimmed, whitespace collapsed, upper-cased
609	     * and common street-type abbreviations expanded) via {@link AddressNormalizer}, otherwise the flat
610	     * {@code address} input is normalized for backward compatibility. Whichever form is supplied, the
611	     * stored {@code address} is composed from the normalized structured lines when present — the
612	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
613	     * appended when an {@code addressLine2} is present — or the normalized flat address otherwise. An
614	     * owner that supplies no address in either form is rejected with 400. Canonicalising the address
615	     * here, before the household checks read it, ensures duplicate detection and the shared household
616	     * id both compare the normalized form. Isolating the address concern in its own helper keeps
617	     * {@link #normalizeOwnerFields} focused on sequencing the per-field canonicalizations.
618	     *
619	     * @param owner the newly mapped owner whose address is canonicalized
620	     */
621	    private void normalizeAddressFields(Owner owner) {
622	        if (owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank()) {
623	            String line1 = addressNormalizer.normalize(owner.getAddressLine1());
624	            owner.setAddressLine1(line1);
625	            String composed = line1;
626	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
627	                String line2 = addressNormalizer.normalize(owner.getAddressLine2());
628	                owner.setAddressLine2(line2);
629	                composed = line1 + " " + line2;
630	            }
631	            owner.setAddress(composed);
632	        }
633	        else {
634	            owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
635	        }
636	    }
637	
638	    /**
639	     * Rejects a supplied email whose domain is on the disposable-domain blocklist
640	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
641	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
642	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
643	     * domain part is left untouched.
644	     *
645	     * @param email the owner's canonicalized email, or {@code null} when absent
646	     */
647	    private void rejectDisposableEmailDomain(String email) {
648	        if (email == null) {
649	            return;
650	        }
651	        int at = email.lastIndexOf('@');
652	        if (at < 0) {
653	            return;
654	        }
655	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
656	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
657	            throw new DisposableEmailException(
658	                "The supplied email domain " + domain + " is on the disposable-domain blocklist");
659	        }
660	    }
661	
662	    /**
663	     * Rejects a supplied registration date that is later than the server's current date with a
664	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
665	     * accepted, and a date on or before today is left for the normal defaulting and business-day
666	     * adjustment.
667	     *
668	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
669	     */
670	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
671	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
672	            throw new InvalidRegistrationDateException(
673	                "The supplied registration date " + registrationDate + " is later than the current date");
674	        }
675	    }
