677	    /**
678	     * The fixed list of public holidays. A registration date that lands on one of these dates is
679	     * rolled forward to the next non-holiday business day, in addition to the weekend rule.
680	     */
681	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
682	        java.time.LocalDate.of(2026, 1, 1),
683	        java.time.LocalDate.of(2026, 1, 26),
684	        java.time.LocalDate.of(2026, 4, 25),
685	        java.time.LocalDate.of(2026, 12, 25),
686	        java.time.LocalDate.of(2026, 12, 28));
687	
688	    /**
689	     * Rolls a registration date forward to a business day: a Saturday, Sunday or listed public
690	     * holiday advances to the next non-holiday weekday, while an ordinary weekday is returned
691	     * unchanged. Applied to the effective registration date (whether supplied in the request or
692	     * defaulted to the server date) so the persisted registration date, every value derived from it
693	     * and the per-day create-limit all use the adjusted business day.
694	     *
695	     * @param date the effective registration date
696	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
697	     */
698	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
699	        java.time.LocalDate adjusted = date;
700	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
701	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
702	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
703	            adjusted = adjusted.plusDays(1);
704	        }
705	        return adjusted;
706	    }
