708	    /**
709	     * Builds the member id '<REGION><FY><HASH8><CHK>' for a newly created owner, where REGION is the
710	     * region derived from the owner's postcode (falling back to the city, via
711	     * {@link LocalityResolver}), FY is the last two digits of the fiscal year of the
712	     * (business-day-adjusted) registration date, HASH8 is the first 8 upper-case hex characters of
713	     * the SHA-256 digest over the owner's normalized telephone concatenated with the last name, and
714	     * CHK is a single Luhn check digit over the decimal digits of '<REGION><FY><HASH8>' (e.g.
715	     * 'NSW26A1B2C3D45'). When that base id already belongs to an existing owner, '-<n>' is appended
716	     * with the smallest n of 2 or more that makes it unique, so distinct owners always receive
717	     * distinct member ids.
718	     *
719	     * @param owner the owner being created, already normalized
720	     * @return the formatted, de-duplicated member id
721	     */
722	    private String memberId(Owner owner) {
723	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
724	        String fy = String.format("%02d",
725	            org.springframework.samples.petclinic.util.FiscalYear.of(owner.getRegistrationDate()) % 100);
726	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
727	        String base = MemberId.format(region, fy, hash8);
728	        return deduplicateCode(base, existingMemberIds());
729	    }
730	
731	    /**
732	     * Collects the member ids already assigned to existing owners, the set a newly built id is
733	     * de-duplicated against. Gathering them here keeps {@link #memberId} focused on building the
734	     * id and lets the uniqueness step (see {@link #deduplicateCode}) work against the ids alone.
735	     *
736	     * @return the member ids currently in use
737	     */
738	    private Set<String> existingMemberIds() {
739	        return existingOwners()
740	            .map(Owner::getMemberId)
741	            .filter(id -> id != null)
742	            .collect(Collectors.toSet());
743	    }
744	
745	    /**
746	     * Returns a unique code for a newly built base identifier: the base itself when it is not already
747	     * taken, otherwise the base with {@code "-<n>"} appended, using the smallest {@code n} of 2 or
748	     * more that makes it unique. Keeping the collision rule in its own helper leaves the identifier's
749	     * construction to its builder and gives the "make it unique" step a single home independent of
750	     * which identifier is being assigned.
751	     *
752	     * @param base  the freshly built identifier, before any uniqueness suffix
753	     * @param taken the identifiers already in use
754	     * @return {@code base} when unused, otherwise the smallest {@code base + "-" + n} not in {@code taken}
755	     */
756	    private String deduplicateCode(String base, Set<String> taken) {
757	        if (!taken.contains(base)) {
758	            return base;
759	        }
760	        int n = 2;
761	        while (taken.contains(base + "-" + n)) {
762	            n++;
763	        }
764	        return base + "-" + n;
765	    }
766	
767	    /**
768	     * Streams the existing owners that the create-time rules match a new owner against. Every
769	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
770	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
771	     * own matching criterion rather than on how the existing owners are retrieved.
772	     *
773	     * @return a stream over all existing owners
774	     */
775	    private Stream<Owner> existingOwners() {
776	        // Exclude soft-deleted owners: a deleted owner is retained for reads but must not block a
777	        // new create, so the duplicate, identity and household checks (and the other create-time
778	        // scans built on this helper) ignore it.
779	        return this.clinicService.findAllOwners().stream()
780	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()));
781	    }
782	
783	    /**
784	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
785	     * enforce the per-city capacity limit and fix an owner's capacity-warning flag at creation time.
786	     *
787	     * @param city the city of the owner being created
788	     * @return the number of existing owners in a matching city
789	     */
790	    private int countOwnersInCity(String city) {
791	        return (int) existingOwners()
792	            .filter(existing -> existing.getCity() != null
793	                && existing.getCity().equalsIgnoreCase(city))
794	            .count();
795	    }
796	
797	    /**
798	     * Counts the existing owners whose registration date is the given adjusted business day. Used
799	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
800	     * owners already carry that business day as their registration date.
801	     *
802	     * @param date the adjusted business-day registration date to match
803	     * @return the number of existing owners registered on that date
804	     */
805	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
806	        return (int) existingOwners()
807	            .filter(existing -> date.equals(existing.getRegistrationDate()))
808	            .count();
809	    }
810	
811	    /**
812	     * Returns the existing owners in the given owner's household, i.e. those sharing its
813	     * deterministic household id (the same last name and postcode). The id is computed via
814	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
815	     * whitespace are treated as the same household. Centralising how "the same household" is matched
816	     * here keeps that definition in one place for every caller.
817	     *
818	     * @param owner the owner being created, with its household id already assigned
819	     * @return the existing owners in the owner's household (possibly empty)
820	     */
821	    private List<Owner> sameHouseholdOwners(Owner owner) {
822	        String householdId = owner.getHouseholdId();
823	        return existingOwners()
824	            .filter(existing -> householdId.equals(
825	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
826	            .toList();
827	    }
828	
829	    /**
830	     * Counts the existing owners who share the given first and last name, compared
831	     * case-insensitively. Used to fix an owner's namesake count at creation time.
832	     *
833	     * @param firstName the first name of the owner being created
834	     * @param lastName  the last name of the owner being created
835	     * @return the number of existing owners with a matching first and last name
836	     */
837	    private int countNamesakes(String firstName, String lastName) {
838	        return (int) existingOwners()
839	            .filter(existing -> existing.getFirstName() != null
840	                && existing.getFirstName().equalsIgnoreCase(firstName)
841	                && existing.getLastName() != null
842	                && existing.getLastName().equalsIgnoreCase(lastName))
843	            .count();
844	    }
845	
846	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
847	    @Override
848	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
849	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
850	        if (currentOwner == null) {
851	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
852	        }
853	        currentOwner.setAddress(ownerFieldsDto.getAddress());
854	        currentOwner.setCity(ownerFieldsDto.getCity());
855	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
856	        currentOwner.setLastName(ownerFieldsDto.getLastName());
857	        // Normalize the telephone to canonical E.164 form so it is stored and returned
858	        // consistently with create; an unformattable value is rejected with 400.
859	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
860	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
861	        this.clinicService.saveOwner(currentOwner);
862	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
863	    }
864	
865	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
866	    @Transactional
867	    @Override
868	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
869	        Owner owner = this.clinicService.findOwnerById(ownerId);
870	        if (owner == null) {
871	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
872	        }
873	        // Soft-delete: flag the owner as deleted and retain the row rather than removing it, so the
874	        // owner is still returned by GET (with 'deleted' true) and only excluded from the create-time
875	        // duplicate and identity checks (see existingOwners()).
876	        owner.setDeleted(true);
877	        this.clinicService.saveOwner(owner);
878	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
879	    }
880	
881	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
882	    @Override
883	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
884	        Owner owner = this.clinicService.findOwnerById(ownerId);
885	        if (owner == null) {
886	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
887	        }
888	        HttpHeaders headers = new HttpHeaders();
889	        Pet pet = petMapper.toPet(petFieldsDto);
890	        owner.setId(ownerId);
891	        pet.setOwner(owner);
892	        pet.getType().setName(null);
893	        this.clinicService.savePet(pet);
894	        PetDto petDto = petMapper.toPetDto(pet);
895	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
896	            .buildAndExpand(pet.getId()).toUri());
897	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
898	    }
899	
900	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
901	    @Override
902	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
903	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
904	        if (currentOwner != null) {
905	            Pet currentPet = this.clinicService.findPetById(petId);
906	            if (currentPet != null) {
907	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
908	                currentPet.setName(petFieldsDto.getName());
909	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
910	                this.clinicService.savePet(currentPet);
911	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
912	            }
913	        }
914	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
915	    }
916	
917	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
918	    @Override
919	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
920	        HttpHeaders headers = new HttpHeaders();
921	        Visit visit = visitMapper.toVisit(visitFieldsDto);
922	        Pet pet = new Pet();
923	        pet.setId(petId);
924	        visit.setPet(pet);
925	        this.clinicService.saveVisit(visit);
926	        VisitDto visitDto = visitMapper.toVisitDto(visit);
927	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
928	            .buildAndExpand(visit.getId()).toUri());
929	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
930	    }
931	
932	
933	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
934	    @Override
935	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
936	        Owner owner = this.clinicService.findOwnerById(ownerId);
937	        if (owner != null) {
938	            Pet pet = owner.getPet(petId);
939	            if (pet != null) {
940	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
941	            }
942	        }
943	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
944	    }
945	}
